       screenshots = EXCLUDED.screenshots, read_minutes = EXCLUDED.read_minutes, published = true,
       published_at = now(), sort_order = EXCLUDED.sort_order, updated_at = now()
 WHERE kb_articles.series = 'Guide' AND kb_articles.published = false AND kb_articles.screenshots = '[]'::jsonb;

INSERT INTO kb_articles (series, folder_id, slug, title, hook, solution_md, screenshots, read_minutes, published, published_at, sort_order)
SELECT 'Guide', f.id, $kb70$guide-meetings$kb70$, $kb71$Meetings — schedule, attend and follow up$kb71$, $kb72$Book client and review meetings, invite team members and clients, and turn action items into tasks.$kb72$, $kb73$The Meetings module keeps every review and client conversation in one place and links it to the client or lead.

![Meetings](shot:1)

## Schedule a meeting

1. Open **Work → Meetings** and click **Add Meeting**.
2. The **Schedule review meeting** page opens. Type a **Subject**, then choose **Who is the meeting with?** — **Client**, **Lead** or **Family** — and search for them by name or PAN.
3. Choose the **Meeting type** (for example Review Meeting) and the **Mode** (for example Online), the **Date**, **Time** and **Duration (minutes)**, and the **Initial status**.
4. Pick the **Assigned RM**, and a joint meeting partner if someone else attends. Add attendees further down the form: search for team members, clients and leads, or type a guest who is not in the CRM.
5. Save. Team attendees see the meeting in their list and calendar.

![Add Meeting](shot:2)

## Work the list

- **Upcoming meetings** is the expandable band at the top; **Past meetings** lists completed ones with notes.
- Use **Table** or **Kanban** at the top right.
- Search, sort and filter with the icons beside the search box.

## Action items are tasks

Every action item has an owner and a due date. When you save, a task is created for the owner automatically and they are notified. Editing the item edits the open task; removing it cancels the task.

## Completing a meeting

Mark a meeting done and it moves to **Past meetings**.$kb73$, $kb74$[{"storageKey":"/kb/meetings.jpg","caption":"Upcoming meetings on top, past meetings below.","alt":"Upcoming meetings on top, past meetings below."},{"storageKey":"/kb/meetings-new.jpg","caption":"Add Meeting: client or lead, date and time, attendees.","alt":"Add Meeting: client or lead, date and time, attendees."}]$kb74$::jsonb, 3, true, now(), 3
